-- deployment: Altering PUBLIC.SEGMENT_REVENUE_VS_TARGET...
CREATE OR REPLACE VIEW PUBLIC.SEGMENT_REVENUE_VS_TARGET AS SELECT -- noqa: ST06
  DATE_TRUNC('MONTH', o.ORDER_DATE) AS TARGET_MONTH,
  c.SEGMENT,
  SUM(o.ORDER_TOTAL) AS ACTUAL_REVENUE,
  t.TARGET_REVENUE,
  SUM(o.ORDER_TOTAL) - t.TARGET_REVENUE AS REVENUE_VARIANCE
FROM PUBLIC.ORDERS o
INNER JOIN PUBLIC.CUSTOMERS c
  ON o.CUSTOMER_ID = c.CUSTOMER_ID
LEFT JOIN PUBLIC.MONTHLY_REVENUE_TARGETS t
  ON DATE_TRUNC('MONTH', o.ORDER_DATE) = t.TARGET_MONTH
 AND c.SEGMENT = t.SEGMENT
GROUP BY 1, 2, 4;


-- deployment: Altering PUBLIC.ORDER_ITEM_DETAILS...
CREATE OR REPLACE VIEW PUBLIC.ORDER_ITEM_DETAILS AS SELECT
  oi.ORDER_ITEM_ID,
  oi.ORDER_ID,
  o.ORDER_DATE,
  o.STATUS,
  c.CUSTOMER_ID,
  c.CUSTOMER_NAME,
  c.SEGMENT,
  p.PRODUCT_ID,
  p.PRODUCT_NAME,
  p.CATEGORY,
  oi.QUANTITY,
  oi.LINE_TOTAL
FROM PUBLIC.ORDER_ITEMS oi
INNER JOIN PUBLIC.ORDERS o
  ON oi.ORDER_ID = o.ORDER_ID
INNER JOIN PUBLIC.CUSTOMERS c
  ON o.CUSTOMER_ID = c.CUSTOMER_ID
INNER JOIN PUBLIC.PRODUCTS p
  ON oi.PRODUCT_ID = p.PRODUCT_ID;


-- deployment: Altering PUBLIC.CUSTOMER_ORDER_SUMMARY...
CREATE OR REPLACE VIEW PUBLIC.CUSTOMER_ORDER_SUMMARY AS SELECT
  c.CUSTOMER_ID,
  c.CUSTOMER_NAME,
  c.SEGMENT,
  COUNT(o.ORDER_ID) AS ORDER_COUNT,
  COALESCE(SUM(o.ORDER_TOTAL), 0) AS TOTAL_SPENT,
  MAX(o.ORDER_DATE) AS LAST_ORDER_DATE
FROM PUBLIC.CUSTOMERS c
LEFT JOIN PUBLIC.ORDERS o
  ON c.CUSTOMER_ID = o.CUSTOMER_ID
GROUP BY 1,2,3;

